from typing import Any, Dict, List, Optional

from pydantic import BaseModel

from rasa.agents.core.types import AgentStatus
from rasa.shared.core.events import Event


class AgentOutput(BaseModel):
    """A class that represents the schema of the output from the agent.

    ``response_message`` is the agent's full reply. For ``input_required`` it is
    stored as the pending question on the agent stack frame; it is also traced.
    ``unsent_response_message`` is the part of that reply the user has not seen
    yet, for agents that already sent some of it as intermediate messages. When
    it is set, the executor utters it in place of ``response_message``. ``None``
    means nothing was sent early. A ``process_agent_output`` rewrite of
    ``response_message`` rebuilds this field from the new text, unless the hook
    assigns the field itself. Assigning the current value, including ``""``,
    still counts as the hook choosing it.
    """

    id: str
    status: AgentStatus
    response_message: Optional[str] = None
    unsent_response_message: Optional[str] = None
    events: Optional[List[Event]] = None
    structured_results: Optional[List[List[Dict[str, Any]]]] = None
    task_id: Optional[str] = None
    context_id: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None
    timestamp: Optional[str] = None
    error_message: Optional[str] = None

    class Config:
        """Skip validation for SlotSet class as pydantic does not know how to
        serialize or handle instances of the class.
        """

        arbitrary_types_allowed = True
